INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Net gift calculation (donee pays gift tax)
(3, 'Estate and Gift Tax', 'Prescott transfers property with a fair market value of $1,200,000 to his nephew, Calloway, on June 1, 2026. As a condition of the gift, Calloway agrees to pay the resulting gift tax of $150,000. What is the amount of Prescott''s taxable gift before the annual exclusion?', '["$1,050,000", "$1,200,000", "$1,350,000", "$150,000"]'::jsonb, 0, 'Under IRC Section 2512 and Diedrich v. Commissioner, when the donee pays the gift tax as a condition of the transfer (a "net gift"), the taxable gift equals the fair market value minus the gift tax paid by the donee: $1,200,000 − $150,000 = $1,050,000. Choice B ($1,200,000) is incorrect because it fails to reduce the gift by the tax obligation assumed by the donee, which constitutes consideration received by the donor.', 'medium', 2),

-- Q2: medium / L2 — QTIP trust marital deduction qualification
(3, 'Estate and Gift Tax', 'Langford establishes a trust on March 10, 2026, giving his wife, Sinclair, all income for life payable at least annually. Upon Sinclair''s death, the trust corpus passes to Langford''s children. The executor makes the QTIP election on the estate tax return. Under IRC Section 2056(b)(7), what is the result?', '["The trust is disqualified from the marital deduction because it is a terminable interest", "The trust qualifies for the marital deduction because the QTIP election was made", "The trust qualifies only if Sinclair has a general power of appointment over the corpus", "The trust is disqualified because the remainder passes to someone other than the surviving spouse"]'::jsonb, 1, 'Under IRC Section 2056(b)(7), qualified terminable interest property (QTIP) qualifies for the unlimited marital deduction when the surviving spouse receives all income for life payable annually or more frequently and the executor makes an irrevocable QTIP election on the estate tax return. Choice A is incorrect because the QTIP exception specifically overrides the terminable interest rule when the statutory requirements and election are satisfied.', 'medium', 2),

-- Q3: easy / L1 — Gift tax return filing deadline
(3, 'Estate and Gift Tax', 'When is the gift tax return (Form 709) generally due for gifts made during the calendar year?', '["March 15 of the following year", "The date the gift is made", "April 15 of the following year", "June 15 of the following year"]'::jsonb, 2, 'Under IRC Section 6075(b), the gift tax return (Form 709) is due on April 15 of the year following the calendar year in which the gift was made, the same deadline as the individual income tax return. An extension of time to file the income tax return also extends the Form 709 deadline. Choice A (March 15) is incorrect because that deadline applies to partnership and S corporation returns, not individual gift tax returns.', 'easy', 1),

-- Q4: easy / L1 — General power of appointment definition
(3, 'Estate and Gift Tax', 'Under the estate tax provisions, what is a general power of appointment?', '["A power exercisable only in favor of the decedent''s creditors", "A power limited to an ascertainable standard relating to health, education, maintenance, or support", "A power shared equally among all trust beneficiaries", "A power exercisable in favor of the holder, the holder''s estate, the holder''s creditors, or creditors of the holder''s estate"]'::jsonb, 3, 'Under IRC Section 2041(b)(1), a general power of appointment is one exercisable in favor of the decedent, the decedent''s estate, the decedent''s creditors, or creditors of the decedent''s estate. Property subject to a general power is included in the gross estate under Section 2041(a)(2). Choice B is incorrect because a power limited to an ascertainable standard (HEMS) is specifically excluded from the definition of a general power.', 'easy', 1),

-- Q5: medium / L3 — Section 2035 gifts within 3 years (life insurance)
(3, 'Estate and Gift Tax', 'Montoya transferred ownership of a $750,000 life insurance policy on her life to an irrevocable trust on September 1, 2024. Montoya died on June 15, 2026. The death benefit is $750,000. Analyze the estate tax consequence of this transfer under IRC Section 2035.', '["The $750,000 death benefit is included in Montoya''s gross estate because the transfer occurred within three years of death", "The policy is excluded from the gross estate because it was transferred to an irrevocable trust", "Only the cash surrender value at the date of transfer is included in the gross estate", "The $750,000 is excluded because Montoya held no incidents of ownership at death"]'::jsonb, 0, 'Under IRC Section 2035(a), if a decedent transfers a life insurance policy within three years of death, the full death benefit is included in the gross estate. Montoya transferred the policy in September 2024 and died in June 2026—less than three years later—so the entire $750,000 is includable. Choice B is incorrect because the irrevocable nature of the trust does not override the three-year rule for life insurance transfers under Section 2035.', 'medium', 3),

-- Q6: hard / L4 — Evaluate GRAT vs outright gift for estate planning
(3, 'Estate and Gift Tax', 'Ellsworth, age 65, holds $4,000,000 in appreciating real estate projected to grow 8% annually. Her estate planner proposes either an outright gift using her remaining $3,500,000 lifetime exemption or a two-year grantor retained annuity trust (GRAT) with annuity payments equaling most of the initial value. Evaluate which strategy better minimizes total transfer taxes if Ellsworth survives the GRAT term.', '["The outright gift is superior because the full $4,000,000 is removed from the estate immediately and sheltered by the exemption", "The GRAT is superior because only the remainder interest exceeding the annuity value is a taxable gift, preserving more lifetime exemption for future transfers", "Both strategies produce identical transfer tax results because the unified credit applies equally to either transfer", "The GRAT is inferior because the retained annuity payments are included in the gross estate under Section 2036"]'::jsonb, 1, 'Under IRC Section 2702, a GRAT''s taxable gift equals the transferred property''s value minus the present value of the retained annuity. A zeroed-out GRAT can transfer appreciation above the Section 7520 rate to beneficiaries with minimal or no taxable gift, preserving lifetime exemption for future transfers. Choice A is incorrect because the outright gift consumes nearly all remaining exemption, leaving no shelter for future transfers, whereas the GRAT achieves wealth transfer while using far less exemption.', 'hard', 4),

-- Q7: hard / L3 — Joint tenancy inclusion with non-spouse (contribution tracing)
(3, 'Estate and Gift Tax', 'Brennan and his brother, Caldwell, purchased a rental property in 2015 as joint tenants with right of survivorship for $600,000. Brennan contributed $450,000 and Caldwell contributed $150,000. At Brennan''s death in 2026, the property is worth $900,000. Analyze what portion is included in Brennan''s gross estate under IRC Section 2040.', '["$450,000, based on Brennan''s original contribution", "$300,000, reflecting Caldwell''s survivorship share subtracted from the total value", "$675,000, reflecting Brennan''s proportionate contribution of 75%", "$900,000, because the full value is included unless the survivor proves contribution"]'::jsonb, 2, 'Under IRC Section 2040(a), for non-spouse joint tenants, the full property value is included in the decedent''s gross estate except to the extent the surviving tenant can prove their contribution. Caldwell contributed 25% ($150,000 of $600,000), so 75% of the $900,000 date-of-death value ($675,000) is included in Brennan''s estate. Choice D is incorrect because Caldwell''s documented $150,000 contribution establishes the 25% exclusion from Brennan''s gross estate.', 'hard', 3),

-- Q8: hard / L4 — Charitable remainder annuity trust vs outright bequest evaluation
(3, 'Estate and Gift Tax', 'Mercer, age 70, wants to transfer $2,000,000 to charity while providing retirement income. Her advisor presents two options: an outright charitable bequest at death or a charitable remainder annuity trust (CRAT) created during life paying 6% annually for 15 years. Evaluate which approach better serves Mercer''s dual goals of lifetime income and transfer tax efficiency.', '["The outright bequest is superior because it eliminates estate tax on the full $2,000,000 with no current income tax consequences", "The CRAT is inferior because the remainder interest gift is not deductible for gift tax purposes", "Both approaches produce equivalent transfer tax results because the charitable deduction applies identically", "The CRAT is superior because it provides a current income tax deduction, removes the remainder from the taxable estate, and generates annual income"]'::jsonb, 3, 'Under IRC Sections 664 and 2055, a CRAT provides a current income tax deduction for the present value of the remainder interest, removes the corpus from the taxable estate, and pays the donor an annuity stream during the trust term. Choice A is incorrect because the outright bequest provides no lifetime income and delays the tax benefit until death, failing to achieve Mercer''s goal of retirement income while still alive.', 'hard', 4),

-- Q9: easy / L1 — Gift of future interest and annual exclusion
(3, 'Estate and Gift Tax', 'Under IRC Section 2503(b), which type of gift does not qualify for the annual gift tax exclusion?', '["A gift of cash to a minor child", "A gift of publicly traded stock", "A gift made through a trust with a Crummey withdrawal power", "A gift of a future interest"]'::jsonb, 3, 'Under IRC Section 2503(b), the annual gift tax exclusion applies only to gifts of present interests—those giving the donee an immediate right to use, possess, or enjoy the property. A gift of a future interest does not qualify because the donee''s enjoyment is deferred. Choice C is incorrect because a Crummey power converts a future interest into a present interest by granting the beneficiary a temporary withdrawal right.', 'easy', 1),

-- Q10: medium / L2 — Below-market loan as gift (Section 7872)
(3, 'Estate and Gift Tax', 'On January 1, 2026, Fitzgerald lends $500,000 to her adult son, Keating, at 0% interest with no fixed repayment date. The applicable federal rate is 4.5%. What is the annual gift tax consequence of this arrangement under IRC Section 7872?', '["No gift occurs because the loan is between family members", "The full $500,000 principal is treated as a taxable gift in the year of the loan", "Fitzgerald is treated as making an annual gift of $22,500, the forgone interest at the AFR", "The gift amount equals the difference between the loan principal and Keating''s net investment income"]'::jsonb, 2, 'Under IRC Section 7872, a below-market demand loan between family members is treated as if the lender made an annual gift equal to the forgone interest: $500,000 × 4.5% = $22,500. The forgone interest is recharacterized as a transfer from lender to borrower each year. Choice B is incorrect because the principal itself is a loan, not a gift—only the below-market interest element is treated as a gift under Section 7872.', 'medium', 2),

-- Q11: easy / L1 — Estate tax payment deadline
(3, 'Estate and Gift Tax', 'When is the federal estate tax return (Form 706) and payment generally due?', '["Within 60 days of the decedent''s death", "Nine months after the decedent''s date of death", "Twelve months after the decedent''s date of death", "April 15 of the year following the decedent''s death"]'::jsonb, 1, 'Under IRC Section 6075(a), the federal estate tax return and payment are due nine months after the decedent''s date of death. An automatic six-month extension for filing is available, but the tax payment remains due at nine months absent a Section 6161 extension. Choice D is incorrect because the estate tax deadline is measured from the date of death, not tied to the calendar-year income tax filing deadline.', 'easy', 1),

-- Q12: easy / L1 — Special use valuation (Section 2032A)
(3, 'Estate and Gift Tax', 'What does IRC Section 2032A allow for estate tax purposes?', '["Valuation of qualifying farm or business real property based on its actual use rather than highest and best use", "Valuation of all estate assets at their value six months after death", "Exclusion of farm property from the gross estate entirely", "A 50% reduction in the fair market value of any real property in the estate"]'::jsonb, 0, 'Under IRC Section 2032A, qualifying real property used in farming or a closely held business may be valued based on its actual use rather than its highest and best use, potentially reducing the gross estate by up to $1,310,000 (2026 indexed). Choice B is incorrect because it describes the alternate valuation date under Section 2032, which is a separate election applying to all estate assets rather than a use-based valuation method.', 'easy', 1),

-- Q13: hard / L4 — Valuation discounts for closely held entity evaluation
(3, 'Estate and Gift Tax', 'Vasquez dies in 2026 owning a 30% interest in Greenfield Holdings LLC, a family-owned real estate company. The pro-rata share of the LLC''s net asset value is $3,000,000. The estate''s appraiser applies a 25% minority interest discount and a 15% lack-of-marketability discount. The IRS challenges both discounts. Evaluate the estate''s position regarding these valuation adjustments.', '["Both discounts are prohibited for family-owned entities under IRC Section 2704(b)", "Only the minority discount is permitted; lack-of-marketability discounts apply solely to publicly traded securities", "The discounts are impermissible because the remaining 70% is held by family members who collectively control the entity", "Both discounts are supportable because a hypothetical willing buyer would pay less for a non-controlling, non-marketable interest in a closely held entity"]'::jsonb, 3, 'Under IRC Section 2031 and Treasury Regulation 20.2031-1(b), estate assets are valued at fair market value—what a hypothetical willing buyer would pay a willing seller. Courts have consistently upheld minority interest and lack-of-marketability discounts for closely held entities because a hypothetical buyer faces real economic limitations. Choice A is incorrect because Section 2704(b) restricts only certain applicable restrictions on liquidation, not all valuation discounts for family entities.', 'hard', 4),

-- Q14: easy / L1 — Unified transfer tax system definition
(3, 'Estate and Gift Tax', 'What is the unified transfer tax system under the Internal Revenue Code?', '["A system that taxes only lifetime gifts and exempts transfers at death", "A system that imposes separate tax rates for estate and gift taxes", "A system that applies gift tax only to transfers exceeding $1,000,000", "A system that applies a single graduated rate schedule to both lifetime gifts and transfers at death"]'::jsonb, 3, 'Under IRC Sections 2001 and 2502, the unified transfer tax system applies one cumulative rate schedule to both lifetime gifts and testamentary transfers, with a single applicable credit amount (unified credit) offsetting tax on both types of transfers. Choice B is incorrect because the estate and gift taxes share the same rate schedule under the unified system rather than having separate rates for each type of transfer.', 'easy', 1),

-- Q15: medium / L3 — Section 2036 retained income interest analysis
(3, 'Estate and Gift Tax', 'Richmond transfers $800,000 of investment securities to an irrevocable trust for his children on April 1, 2023, but retains the right to receive all trust income for the rest of his life. Richmond dies on November 20, 2026, when the securities are worth $1,100,000. Analyze the estate tax consequence of Richmond''s retained interest.', '["Only $800,000, the original transfer value, is included in the gross estate", "The full $1,100,000 date-of-death value is included in the gross estate because Richmond retained a life income interest", "Only the $300,000 in appreciation is included in the gross estate as an incomplete gift", "The trust is excluded from the gross estate because the transfer was irrevocable"]'::jsonb, 1, 'Under IRC Section 2036(a)(1), if a decedent transfers property but retains the right to income for life, the full date-of-death value is included in the gross estate. Richmond retained all trust income, so the entire $1,100,000 is includable regardless of the trust''s irrevocable status. Choice D is incorrect because irrevocability alone does not exclude property from the estate when the transferor retains a life income interest under Section 2036.', 'medium', 3),

-- Q16: medium / L2 — Gift tax computation (cumulative method)
(3, 'Estate and Gift Tax', 'Donovan made $2,000,000 in cumulative taxable gifts through 2025. In 2026, Donovan makes additional taxable gifts of $500,000 after the annual exclusion. The gift tax rate on the cumulative amount from $2,000,000 to $2,500,000 is 40%. Donovan has no remaining applicable credit. What is Donovan''s gift tax liability for 2026?', '["$0, because the gift tax applies only at death", "$100,000, using a 20% marginal rate on the $500,000", "$200,000, computed as 40% of the current-year taxable gifts", "$500,000, the entire gift amount taxed at the maximum rate"]'::jsonb, 2, 'Under IRC Section 2502, gift tax is computed on cumulative lifetime taxable gifts using the unified rate schedule. The tax on $2,500,000 cumulative gifts minus the tax on $2,000,000 prior gifts equals the current-year tax. At a 40% marginal rate and no remaining credit, the 2026 liability is $500,000 × 40% = $200,000. Choice B is incorrect because the marginal rate is determined by the cumulative gift total, not by applying a lower rate to current-year gifts in isolation.', 'medium', 2),

-- Q17: medium / L3 — Adjusted taxable gifts in estate tax computation
(3, 'Estate and Gift Tax', 'Weston dies in 2026 with a gross estate of $12,000,000. During her lifetime, Weston made $3,000,000 in taxable gifts on which no gift tax was paid due to the unified credit. The estate claims $1,500,000 in deductions. Analyze how the lifetime gifts affect the estate tax computation.', '["The $3,000,000 in lifetime gifts reduces the gross estate, resulting in an $8,500,000 taxable estate", "The lifetime gifts are disregarded because no gift tax was paid on them", "The adjusted taxable gifts increase the applicable exclusion amount by $3,000,000", "The $3,000,000 in adjusted taxable gifts is added to the taxable estate to compute the tentative tax, then the gift tax payable is subtracted"]'::jsonb, 3, 'Under IRC Section 2001(b), the tentative estate tax is calculated on the sum of the taxable estate ($10,500,000) plus adjusted taxable gifts ($3,000,000). The computed tax is then reduced by the gift tax that would have been payable on those gifts. This mechanism ensures cumulative taxation at the highest marginal rate. Choice A is incorrect because adjusted taxable gifts do not reduce the gross estate; they are added to the taxable estate in the tentative tax computation.', 'medium', 3),

-- Q18: easy / L1 — QDOT for non-citizen surviving spouse
(3, 'Estate and Gift Tax', 'What is the purpose of a qualified domestic trust (QDOT) under IRC Section 2056A?', '["To allow the marital deduction for property passing to a surviving spouse who is not a U.S. citizen", "To defer capital gains tax on property transferred between spouses", "To exclude trust income from the surviving spouse''s gross income", "To provide an additional estate tax exemption for noncitizen decedents"]'::jsonb, 0, 'Under IRC Section 2056A, a qualified domestic trust (QDOT) permits the estate to claim the unlimited marital deduction for property passing to a surviving spouse who is not a U.S. citizen. Without a QDOT, the marital deduction is denied for transfers to noncitizen spouses. Choice B is incorrect because the QDOT addresses estate tax marital deduction eligibility, not capital gains tax deferral between spouses.', 'easy', 1),

-- Q19: hard / L4 — Section 529 plan 5-year election evaluation
(3, 'Estate and Gift Tax', 'In January 2026, Palmer contributes $95,000 to a Section 529 education savings plan for her granddaughter, Orozco. Palmer elects to spread the gift evenly over five years under IRC Section 529(c)(2)(B). Palmer makes no other gifts to Orozco during 2026 through 2030. The annual exclusion is $19,000. Evaluate whether Palmer must use any lifetime exemption for this contribution.', '["Palmer must use $76,000 of her lifetime exemption because only one annual exclusion applies to a single transfer", "Palmer owes immediate gift tax on $95,000 because the five-year election does not apply to grandchildren", "Palmer uses no lifetime exemption because the five-year election allocates $19,000 per year, each fully covered by the annual exclusion", "Palmer uses $14,000 of lifetime exemption because the five-year allocation creates an excess in year one"]'::jsonb, 2, 'Under IRC Section 529(c)(2)(B), a contributor may elect to treat a lump-sum 529 contribution as made ratably over five years for gift tax purposes. Palmer''s $95,000 ÷ 5 = $19,000 per year, exactly matching the annual exclusion, so no taxable gift results and no lifetime exemption is consumed. Choice A is incorrect because the five-year election specifically permits spreading the contribution across multiple years to maximize annual exclusion use.', 'hard', 4),

-- Q20: medium / L3 — General power of appointment trust inclusion analysis
(3, 'Estate and Gift Tax', 'Hoffman dies in 2026 holding a general power of appointment over a trust worth $2,500,000 created by her mother. Hoffman never exercised the power during her lifetime. At death, the trust passes to Hoffman''s siblings under the trust''s default provisions. Analyze whether the trust assets are included in Hoffman''s gross estate.', '["The trust is excluded because Hoffman never exercised the power during her lifetime", "The trust is excluded because the assets pass to Hoffman''s siblings, not to Hoffman''s estate", "Only the income earned by the trust during Hoffman''s lifetime is included", "The full $2,500,000 is included in Hoffman''s gross estate because she held a general power of appointment at death"]'::jsonb, 3, 'Under IRC Section 2041(a)(2), property subject to a general power of appointment held by the decedent at death is included in the gross estate regardless of whether the power was exercised. Hoffman''s mere possession of the general power at death triggers inclusion of the entire $2,500,000. Choice A is incorrect because Section 2041 includes property over which the decedent held the power at death—exercise is not required for estate inclusion.', 'medium', 3),

-- Q21: medium / L2 — Taxable termination (GST)
(3, 'Estate and Gift Tax', 'In 2026, a trust created by Pearson''s grandmother for Pearson''s benefit terminates by its terms. The $800,000 corpus passes to Pearson''s daughter, who is a skip person relative to the grandmother. No non-skip persons hold any interest after termination. What type of generation-skipping transfer has occurred?', '["A taxable termination under IRC Section 2612(a)", "A taxable distribution under IRC Section 2612(b)", "A direct skip under IRC Section 2612(c)", "No generation-skipping transfer because Pearson was the trust beneficiary"]'::jsonb, 0, 'Under IRC Section 2612(a), a taxable termination occurs when an interest in a trust terminates and no non-skip person holds an interest after the termination. Since Pearson''s interest ended and the assets pass to a skip person (two generations below the transferor), this is a taxable termination. Choice C is incorrect because a direct skip is a transfer directly to a skip person that is subject to estate or gift tax, not a termination of a trust interest.', 'medium', 2),

-- Q22: hard / L4 — Family limited partnership Section 2036 risk evaluation
(3, 'Estate and Gift Tax', 'Torres, age 72, transfers $6,000,000 in marketable securities to a family limited partnership (FLP), receiving a 95% limited partner interest and a 5% general partner interest. Torres then gifts limited partnership interests to her children, claiming minority and marketability discounts. Torres''s CPA must assess the IRS challenge risk under Section 2036. Evaluate the most critical factor determining whether the FLP withstands scrutiny.', '["Whether the FLP was funded with publicly traded securities rather than operating business assets", "Whether Torres retained sufficient assets outside the FLP to maintain her standard of living, demonstrating a legitimate nontax purpose", "Whether the total discounts claimed exceed 30% of the transferred property''s fair market value", "Whether Torres gifted more than 50% of the limited partnership interests during her lifetime"]'::jsonb, 1, 'Under IRC Section 2036 and case law (Estate of Bongard, Estate of Strangi), the IRS challenges FLPs when the transferor retains an implied agreement to use partnership assets for personal benefit. Courts focus on whether the transferor maintained sufficient outside assets for living expenses, establishing a legitimate nontax business purpose. Choice A is incorrect because while asset type may be relevant, the decisive factor is whether the transferor demonstrated economic independence from the FLP assets.', 'hard', 4),

-- Q23: medium / L2 — Charitable gift deduction for gift tax
(3, 'Estate and Gift Tax', 'On August 15, 2026, Chambers donates $350,000 in appreciated stock to a qualified public charity. The stock was purchased for $100,000. Chambers has made no other gifts in 2026. What is Chambers''s taxable gift for gift tax purposes?', '["$0, because charitable gifts to qualified organizations are fully deductible for gift tax purposes", "$331,000, after applying the $19,000 annual exclusion to the charitable gift", "$250,000, because only the donor''s adjusted basis is deductible", "$350,000, because charitable gifts do not qualify for the gift tax charitable deduction"]'::jsonb, 0, 'Under IRC Section 2522, gifts to qualified charitable organizations are fully deductible for gift tax purposes with no percentage-of-income limitations, unlike the income tax charitable deduction. The entire $350,000 fair market value is offset by the gift tax charitable deduction, resulting in $0 taxable gift. Choice D is incorrect because Section 2522 specifically provides an unlimited gift tax charitable deduction for transfers to qualifying organizations.', 'medium', 2),

-- Q24: medium / L2 — Basis with alternate valuation election
(3, 'Estate and Gift Tax', 'Fletcher dies on January 5, 2026, owning shares of Waverly Corp. valued at $400,000 at death. The executor elects the alternate valuation date under IRC Section 2032. On July 5, 2026, the shares are worth $340,000 and have not been distributed. What is the beneficiary''s income tax basis in the Waverly Corp. shares?', '["$400,000, the date-of-death value regardless of any election", "$370,000, the average of the date-of-death and alternate valuation date values", "$340,000, the fair market value on the alternate valuation date", "$0, because the alternate valuation election eliminates the stepped-up basis"]'::jsonb, 2, 'Under IRC Sections 2032 and 1014(a), when the executor elects alternate valuation, the beneficiary''s basis equals the fair market value on the alternate valuation date (six months after death) rather than the date-of-death value. The shares are valued at $340,000 on July 5, 2026. Choice A is incorrect because the alternate valuation election overrides the standard date-of-death valuation, and basis follows the value used for estate tax purposes.', 'medium', 2),

-- Q25: medium / L2 — Gift splitting consent requirements
(3, 'Estate and Gift Tax', 'On October 1, 2026, Rivera gives $80,000 to his friend Martinez. Rivera''s wife, Avila, did not contribute to the gift but is willing to consent to gift splitting. Under IRC Section 2513, what must occur for the election to be valid?', '["Rivera must file Form 709 alone, and Avila files a separate Form 709 for her half", "Both spouses must consent to split all gifts made by either spouse during the entire calendar year on their Forms 709", "Only the donor spouse must sign Form 709; the non-donor spouse''s consent is implied by marriage", "Gift splitting requires a written agreement filed with the IRS before the gift date"]'::jsonb, 1, 'Under IRC Section 2513, gift splitting requires both spouses to consent on their gift tax returns, and the election applies to all gifts made by either spouse during the entire calendar year. Couples cannot selectively split individual gifts while excluding others in the same year. Choice C is incorrect because Section 2513(a)(2) explicitly requires the non-donor spouse to signify consent on the return—consent is never implied by marriage alone.', 'medium', 2),

-- Q26: easy / L2 — Part-gift, part-sale transaction
(3, 'Estate and Gift Tax', 'On May 1, 2026, Dawson sells a vacation home with a fair market value of $350,000 to his daughter, Chen, for $150,000. What is the gift tax consequence of this transfer?', '["No gift occurs because the property was sold rather than gifted", "Dawson made a gift of $200,000, the difference between fair market value and the amount received", "Dawson made a gift of $350,000, the full fair market value of the property", "Dawson made a gift of $150,000, the amount Chen paid"]'::jsonb, 1, 'Under IRC Section 2512(b), when property is transferred for less than adequate and full consideration, the excess of the fair market value over the consideration received is treated as a gift: $350,000 − $150,000 = $200,000. This is a part-gift, part-sale transaction. Choice A is incorrect because a transfer for below-market consideration triggers gift tax on the difference between fair market value and the price paid under Section 2512(b).', 'easy', 2),

-- Q27: medium / L3 — Incomplete gift (revocable transfer) analysis
(3, 'Estate and Gift Tax', 'On March 15, 2026, Garrison transfers $500,000 to a trust for the benefit of his niece, Palmer. However, Garrison retains the power to revoke the trust at any time and reclaim the assets. Analyze the gift tax consequence of this transfer.', '["No taxable gift has occurred because the transfer is incomplete due to Garrison''s retained power to revoke", "The gift is complete and taxable at $481,000 after the annual exclusion", "The gift is complete but fully offset by the lifetime exemption, so no tax is owed", "The $500,000 is a taxable gift because it was placed in a trust"]'::jsonb, 0, 'Under IRC Section 2511 and Treas. Reg. 25.2511-2(c), a gift is incomplete if the donor retains the power to revest the property in himself. Garrison''s unrestricted revocation power means the transfer is not a completed gift for gift tax purposes, so no gift tax applies. Choice D is incorrect because the form of the transfer (trust versus outright) does not determine completeness; the donor''s retained dominion and control is the decisive factor.', 'medium', 3),

-- Q28: easy / L1 — Political organization gift tax treatment
(3, 'Estate and Gift Tax', 'Under IRC Section 2501(a)(4), how are transfers to political organizations treated for gift tax purposes?', '["Taxable gifts subject to the unified rate schedule", "Deductible gifts eligible for the gift tax charitable deduction under Section 2522", "Exempt from gift tax entirely", "Subject to gift tax but eligible for the annual exclusion only"]'::jsonb, 2, 'Under IRC Section 2501(a)(4), transfers to political organizations as defined in Section 527(e)(1) are not treated as transfers by gift and are completely exempt from the gift tax. This is a statutory exclusion, not a deduction. Choice B is incorrect because political organizations do not qualify for the Section 2522 gift tax charitable deduction; they receive a separate statutory exemption from the gift tax.', 'easy', 1),

-- Q29: medium / L3 — Disclaimer impact on estate tax planning
(3, 'Estate and Gift Tax', 'Ortega dies in 2026 leaving $16,000,000 to her son, Blake, who already has a taxable estate of $10,000,000. Blake''s advisor recommends he disclaim a portion of the inheritance so it passes to Blake''s children under the will''s default provision. Analyze why this disclaimer strategy reduces combined family transfer taxes.', '["The disclaimer converts the inheritance into a nontaxable gift from Blake to his children", "The disclaimed property bypasses Blake''s estate entirely, avoiding a second layer of estate tax at Blake''s subsequent death", "The disclaimer entitles Blake to an additional unified credit on the disclaimed amount", "The disclaimer reduces Ortega''s gross estate, lowering the estate tax on her return"]'::jsonb, 1, 'Under IRC Section 2518, a qualified disclaimer causes the property to pass as if the disclaimant predeceased the decedent, bypassing the disclaimant''s estate entirely. By disclaiming, Blake prevents the inherited assets from being taxed again in his own estate at death, reducing combined family transfer taxes across generations. Choice D is incorrect because the disclaimer does not reduce the decedent''s gross estate; the property still passes through the estate to an alternative beneficiary.', 'medium', 3),

-- Q30: medium / L3 — Section 6166 installment payment for closely held business
(3, 'Estate and Gift Tax', 'Ramirez dies in 2026 owning a 45% interest in a closely held business valued at $8,000,000. The total gross estate is $14,000,000. The estate qualifies under IRC Section 6166. Analyze the primary benefit of making the Section 6166 election.', '["The estate may defer estate tax attributable to the closely held business interest, paying only interest for four years and then the tax in up to ten annual installments", "The estate receives a full exemption from estate tax on the closely held business interest", "The election allows the estate to value the business at 50% of fair market value", "The estate may defer all estate taxes, including those on non-business assets, for up to 14 years"]'::jsonb, 0, 'Under IRC Section 6166, if a closely held business exceeds 35% of the adjusted gross estate, the estate may elect to defer the estate tax attributable to the business interest—paying only interest for four years, then the tax in up to ten annual installments. This provides liquidity relief for illiquid business estates. Choice D is incorrect because Section 6166 deferral applies only to estate tax attributable to the closely held business interest, not to taxes on non-business assets.', 'medium', 3)
;

COMMIT;
